"""Build a source-owned, bounded read-only native ARM64 resource query helper."""
from pathlib import Path
import argparse,hashlib,json,os,re,subprocess
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();W=Path(__file__).resolve().parent;assert not a.output.exists();a.output.mkdir(parents=True);sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();files=[W/'resource.go',W/'main_windows.go'];sources={p.name:sha(p)for p in files};text=files[1].read_text();calls=re.findall(r'\.NewProc\("([^"]+)"\)',text);expected=['CM_Get_Device_ID_List_SizeW','CM_Get_Device_ID_ListW','CM_Locate_DevNodeW','CM_Get_DevNode_Status','CM_Get_DevNode_Registry_PropertyW','CM_Get_First_Log_Conf','CM_Get_Next_Log_Conf','CM_Free_Log_Conf_Handle','CM_Get_Next_Res_Des','CM_Get_Res_Des_Data_Size','CM_Get_Res_Des_Data','CM_Free_Res_Des_Handle','GetSystemFirmwareTable'];assert calls==expected;assert '//go:uintptrescapes\nfunc cr('in text
version=subprocess.check_output(['go','version'],text=True).strip();assert 'go1.26.4 'in version
out=a.output/'g62-resources-arm64.exe';env=dict(os.environ,GOOS='windows',GOARCH='arm64',CGO_ENABLED='0');cmd=['go','build','-trimpath','-buildvcs=false','-gcflags=-m','-ldflags=-s -w -buildid=','-o',str(out.resolve()),*[str(p.resolve())for p in files]];q=subprocess.run(cmd,env=env,capture_output=True,text=True);assert not q.returncode,(q.stdout,q.stderr);assert sources=={p.name:sha(p)for p in files}
heap=[line for line in q.stderr.splitlines()if 'moved to heap:'in line];assert any('moved to heap: h'in line for line in heap)and any('moved to heap: next'in line for line in heap)and any('moved to heap: dn'in line for line in heap);(a.output/'pointer-lifetime.txt').write_text('\n'.join(heap)+'\n')
v={'source_files_sha256':sources,'binary_sha256':sha(out),'bytes':out.stat().st_size,'Go_version':version,'target':'windows/arm64','CGO_ENABLED':'0','API_calls':calls,'heap_pointer_lifetime_verified':True,'compiler_pointer_escape_lines':heap,'native_operations':0};(a.output/'build.json').write_text(json.dumps(v,indent=2)+'\n');print(json.dumps({k:v for k,v in v.items()if k!='compiler_pointer_escape_lines'}))
